with by_region as (
    select year, value_anchored_po as value_change from doorstep.export_ch6_by_year where cbsa_title = 'La Crosse'
), by_year as (
    select year, value_change as value_change from by_region where year >= 2013 and year < 2019
), by_period as (
    select year, value_change as value_change from by_year where period = 'quarter'
)
select max(value_change) - min(value_change) as value_change from by_period
