```sql
select T1.placement from (
    select cbsa_code, placement from (
        select cbsa_code, placement, row_number() over (partition by cbsa_code order by permits desc) as placement from doorstep.fct_metro_year where year = 2013
    ) as T2
) as T1 join (
    select * from doorstep.ch4_cells where cbsa_title in ('Louisville/Jefferson County, KY-IN', 'Naples-Marco Island, FL', 'New Orleans-Metairie, LA', 'San Jose-Sunnyvale-Santa Clara, CA', 'Las Vegas-Henderson-North Las Vegas, NV')
) as T3 on T1.cbsa_code = T3.cbsa_code where T3.cbsa_title = 'New Orleans-Metairie, LA' order by T1.placement
```

```sql
select sum(change) / sum(start) * 100 as value from (
  select (b.payment_share - a.payment_share) as change, a.payment_share as start
  from (
    select * from doorstep.ch1_national_series
    where year = 2006
  ) as a
  join (
    select * from doorstep.ch1_national_series
    where year = 2012
  ) as b
) as sub
```

```sql
with early_rates as (
    select 2006 as year, avg(rate) as early_rate from doorstep.ch1_national_series where year = 2006
), late_rates as (
    select 2008 as year, avg(rate) as late_rate from doorstep.ch1_national_series where year = 2008
), rate_changes as (
    select early_rate - late_rate as rate_change from early_rates join late_rates on true
)
select rate_change as value from rate_changes
```
